  @override
  String get learningJourneyDetailActionReviewJourney => 'Rezensionsreise';

  @override
  String get learningJourneyBeautifulCharacterTitle => 'Schöner Charakter';

  @override
  String get learningJourneyBeautifulCharacterSubtitle =>
      'Wachsen Sie durch die Eigenschaften, die den Glauben und das tägliche Leben verschönern.';

  @override
  String get learningJourneyBeautifulCharacterDescription =>
      'Folgen Sie einer geführten Reise durch Aufrichtigkeit, Geduld, Dankbarkeit, Demut, Vergebung, Selbstbeherrschung, Freundlichkeit und abschließende Reflexion.';

  @override
  String get learningJourneyBeautifulCharacterOutcome1 =>
      'Verstehen Sie die Kerneigenschaften eines schönen islamischen Charakters';

  @override
  String get learningJourneyBeautifulCharacterOutcome2 =>
      'Verbinden Sie den Charakter mit Anbetung, Beziehungen und täglichen Entscheidungen';

  @override
  String get learningJourneyBeautifulCharacterOutcome3 =>
