  @override
  String get learningJourneyCharacterIkhlasStageTitle => 'Aufrichtigkeit';

  @override
  String get learningJourneyCharacterIkhlasStageSummary =>
      'Beginnen Sie mit Ikhlas, damit Ihre Taten allein in Allah verwurzelt sind.';

  @override
  String get learningJourneyCharacterSabrStageTitle => 'Geduld';

  @override
  String get learningJourneyCharacterSabrStageSummary =>
      'Erfahren Sie, wie Sabr den Glauben trotz Härten, Verzögerungen und Disziplin festigt.';

  @override
  String get learningJourneyCharacterShukrStageTitle => 'Dankbarkeit';

  @override
  String get learningJourneyCharacterShukrStageSummary =>
      'Betrachten Sie Dankbarkeit als Anbetung des Herzens, der Zunge und der täglichen Entscheidungen.';

  @override
  String get learningJourneyCharacterHumilityStageTitle => 'Demut';

  @override
  String get learningJourneyCharacterHumilityStageSummary =>
      'Übe ein demütiges Herz und bleibe dennoch fest bei der Wahrheit.';

  @override
  String get learningJourneyCharacterForgivenessStageTitle => 'Vergebung';

  @override
  String get learningJourneyCharacterForgivenessStageSummary =>
      'Erfahren Sie, wann Vergebung das Herz heilt und die Würde wiederherstellt.';

  @override
  String get learningJourneyCharacterAngerStageTitle => 'Wut kontrollieren';

  @override
  String get learningJourneyCharacterAngerStageSummary =>
      'Trainieren Sie sich darin, innezuhalten, Ihren Ärger zu zügeln und mit Weisheit zu reagieren.';

  @override
  String get learningJourneyCharacterKindnessStageTitle => 'Freundlichkeit';

  @override
  String get learningJourneyCharacterKindnessStageSummary =>
      'Tragen Sie Barmherzigkeit in Ihre Sprache, Ihren Dienst und Ihre alltäglichen Beziehungen.';

  @override
  String get learningJourneyCharacterCompletionStageTitle =>
      'Abschlussreflexion';

  @override
  String get learningJourneyCharacterCompletionStageSummary =>
      'Sammeln Sie, was Sie gelernt haben, und wählen Sie eine Charaktereigenschaft aus, die Sie weiter üben möchten.';

  @override
  String get learningJourneyWordsTopReviewSuggestion =>
      'Gehen Sie morgen noch einmal einen kleinen Wortsatz durch und bemerken Sie diese Wörter dann, wenn Sie das nächste Mal den Koran lesen.';

  @override
  String get learningJourneyWordsReviewSuggestion =>
      'Verwenden Sie kurze, häufige Überprüfungen anstelle langer Sitzungen, damit die Anerkennung leicht und gleichmäßig bleibt.';

  @override
  String get learningJourneyWordsPatternsActionStep =>
      'Wählen Sie eine kleine Wortfamilie aus, die Sie bei Ihrer nächsten Rezitation oder Lesesitzung beachten möchten.';

  @override
  String get learningJourneyWordsPatternsReviewSuggestion =>
      'Kommen Sie morgen wieder und sehen Sie, ob die gleichen Bedeutungen in bekannten Versen wieder auftauchen.';

  @override
  String get learningJourneyWisdomDailyQuoteTitle =>
      'Erhalten Sie eine kluge Erinnerung';

  @override
  String get learningJourneyWisdomDailyQuoteIntro =>
      'Ein Gegenstand der täglichen Weisheit sollte klein genug sein, um ihn zu tragen, und tief genug, um ihn später am Tag wieder zu öffnen.';

  @override
  String get learningJourneyWisdomDailyQuoteSection1Title =>
      'Was Daily Wisdom sammelt';

  @override
  String get learningJourneyWisdomDailyQuoteSection1Body =>
      'Daily Wisdom bringt kurze Erinnerungen aus Koran, Hadith, prophetischem Beispiel und Reflexion zusammen, eine nach der anderen. Das Ziel ist nicht Menge. Das Ziel ist eine wahre Erinnerung, die bei Ihnen bleibt.';

  @override
  String get learningJourneyWisdomDailyQuoteSection2Title =>
      'Wie man einen Gegenstand gut nutzt';

  @override
  String get learningJourneyWisdomDailyQuoteSection2Body =>
      'Lesen Sie langsam, behalten Sie eine Idee im Auge und lassen Sie sie zu einer Entscheidung oder einem Dua werden, bevor der Tag weitergeht.';

  @override
  String get learningJourneyWisdomDailyQuoteBullet1 =>
      'Wählen Sie eine Zeile, anstatt zu versuchen, sich alles zu merken.';

  @override
  String get learningJourneyWisdomDailyQuoteBullet2 =>
      'Kehren Sie später am Tag noch einmal dorthin zurück.';

  @override
  String get learningJourneyWisdomDailyQuoteBullet3 =>
      'Lassen Sie sich davon auf eine tiefere Reise hinweisen, wenn Sie dazu bereit sind.';

  @override
  String get learningJourneyWisdomDailyQuoteTakeaway1 =>
      'Eine kleine Erinnerung kann für einen ganzen Tag reichen.';

  @override
  String get learningJourneyWisdomDailyQuoteTakeaway2 =>
      'Tägliche Weisheit funktioniert am besten, wenn sie einfach und konsistent bleibt.';

  @override
  String get learningJourneyWisdomDailyQuoteTakeaway3 =>
      'Kurze Erinnerungen sollten zu tieferem Lernen führen und es nicht ersetzen.';

  @override
  String get learningJourneyWisdomDailyQuoteReflection =>
      'Welche Erinnerung brauchen Sie heute mehr als zusätzliche Informationen?';

  @override
  String get learningJourneyWisdomShortLessonTitle =>
      'Verwandeln Sie Weisheit in eine kurze Lektion';

  @override
  String get learningJourneyWisdomShortLessonIntro =>
      'Eine kurze Lektion hilft einer täglichen Erinnerung dabei, Wurzeln zu schlagen. Es erklärt gerade genug, um die Erinnerung nutzbar zu machen.';

  @override
  String get learningJourneyWisdomShortLessonSection1Title =>
      'Konsistenter Erklärungsstil';

  @override
  String get learningJourneyWisdomShortLessonSection1Body =>
      'Unabhängig davon, ob es sich bei der Quelle um einen Hadith, einen Vers, ein prophetisches Ereignis oder eine Aufforderung zum Nachdenken handelt, sollte die Erklärung ruhig, praktisch und anfängerfreundlich bleiben. Das sorgt dafür, dass Daily Wisdom kohärent bleibt.';

  @override
  String get learningJourneyWisdomShortLessonSection2Title =>
      'Wohin die Lektion führen soll';

  @override
  String get learningJourneyWisdomShortLessonSection2Body =>
      'Eine kurze Lektion sollte mit einem nächsten Schritt enden. Der nächste Schritt könnte eine Reise, ein Werkzeug, ein kurzer Gottesdienst oder eine praktische Entscheidung sein.';

  @override
  String get learningJourneyWisdomShortLessonBullet1 =>
      'Halten Sie die Erklärung kurz genug, um sie schnell noch einmal lesen zu können.';

  @override
  String get learningJourneyWisdomShortLessonBullet2 =>
      'Binden Sie die Erinnerung an das tägliche Leben.';

  @override
  String get learningJourneyWisdomShortLessonBullet3 =>
      'Bieten Sie einen klaren Weg an, um tiefer zu gehen.';

  @override
  String get learningJourneyWisdomShortLessonTakeaway1 =>
      'Guter täglicher Unterricht ist übersichtlich und nicht überfüllt.';

  @override
  String get learningJourneyWisdomShortLessonTakeaway2 =>
      'Eine kurze Lektion soll Herz und Verstand gemeinsam helfen.';

  @override
  String get learningJourneyWisdomShortLessonTakeaway3 =>
      'Daily Wisdom sollte ganz natürlich zu den umfassenderen Reisen führen.';

  @override
  String get learningJourneyWisdomShortLessonReflection =>
      'Welche Art von täglicher Erinnerung öffnet Sie am meisten: ein Vers, ein Hadith, eine Geschichte oder eine Frage zum Nachdenken?';

  @override
  String get learningJourneyWisdomPracticeTitle =>
      'Weisheit in die Praxis umsetzen';

  @override
  String get learningJourneyWisdomPracticeIntro =>
      'Der Zweck der täglichen Weisheit besteht nicht darin, Zitate zu sammeln. Es geht darum, Sprache, Absicht, Gewohnheiten und Aufmerksamkeit sanft zu ändern.';

  @override
  String get learningJourneyWisdomPracticeSection1Title => 'Eine Aktion genügt';

  @override
  String get learningJourneyWisdomPracticeSection1Body =>
      'Wählen Sie eine kleine Handlung, die zur Erinnerung passt: innehalten, bevor Sie sprechen, Allah laut danken, schnell verzeihen, einen Vers wiederholen oder zum Dhikr zurückkehren.';

  @override
  String get learningJourneyWisdomPracticeSection2Title =>
      'Bauen Sie einen wiederholbaren Rhythmus auf';

  @override
  String get learningJourneyWisdomPracticeSection2Body =>
      'Ein stabiler Rhythmus könnte sein: Öffnen Sie einen Weisheitsgegenstand, behalten Sie einen Satz bei, handeln Sie bei einem Schritt und begeben Sie sich später erneut auf eine verwandte Reise.';

  @override
  String get learningJourneyWisdomPracticeBullet1 =>
      'Überladen Sie den Tag nicht mit zu vielen Zielen.';

  @override
  String get learningJourneyWisdomPracticeBullet2 =>
      'Lassen Sie die Wiederholung Einsicht in Gewohnheit verwandeln.';

  @override
  String get learningJourneyWisdomPracticeBullet3 =>
      'Nutzen Sie verwandte Reisen, um tiefer zu gehen.';

  @override
  String get learningJourneyWisdomPracticeTakeaway1 =>
      'Weisheit wird nützlich, wenn sie das Handeln verändert.';

  @override
  String get learningJourneyWisdomPracticeTakeaway2 =>
      'Eine kleine wiederholte Handlung ist stärker als eine große, kurzlebige Absicht.';

  @override
  String get learningJourneyWisdomPracticeTakeaway3 =>
      'Daily Wisdom sollte Sie zurück zu Ihrem umfassenderen Lernen führen.';

  @override
  String get learningJourneyWisdomPracticeReflection =>
      'Was ist eine kleine Aktion, die Sie heute tun können, damit diese Erinnerung zu gelebtem Wissen wird?';

  @override
  String get learningJourneyWisdomPracticeActionStep =>
      'Bevor der Tag endet, kehren Sie noch einmal zu dieser Erinnerung zurück und fragen Sie, ob sie eine Wahl, ein Wort oder ein Dua geändert hat.';

  @override
  String get learningJourneyCharacterIkhlasTitle => 'Aufrichtigkeit (Ikhlas)';

  @override
  String get learningJourneyCharacterIkhlasIntro =>
      'Ikhlas bedeutet, das Richtige für Allah zu tun – nicht zur Zurschaustellung, für Lob oder Kontrolle.';

  @override
  String get learningJourneyCharacterIkhlasSection1Title =>
      'Was Aufrichtigkeit bewirkt';

  @override
  String get learningJourneyCharacterIkhlasSection1Body =>
      'Aufrichtigkeit reinigt Taten von innen heraus. Zwei Menschen mögen äußerlich dieselbe Tat vollbringen, doch wer Allah allein sucht, trägt bei Ihm ein anderes Gewicht.';

  @override
  String get learningJourneyCharacterIkhlasSection2Title =>
      'Wie Aufrichtigkeit im wirklichen Leben erscheint';

  @override
  String get learningJourneyCharacterIkhlasSection2Body =>
      'Ikhlas zeigt sich, wenn Sie weiterhin Gutes tun, auch wenn es niemand bemerkt, und wenn Sie Ihre Absicht korrigieren, wann immer Stolz Einzug zu halten versucht.';

  @override
  String get learningJourneyCharacterIkhlasBullet1 =>
      'Erneuern Sie Ihre Absicht vor einer guten Tat.';

  @override
  String get learningJourneyCharacterIkhlasBullet2 =>
      'Tun Sie, wenn möglich, privat etwas Gutes.';

  @override
  String get learningJourneyCharacterIkhlasBullet3 =>
      'Wenn Sie Lob erreicht, danken Sie Allah und halten Sie Ihr Herz beständig.';

  @override
  String get learningJourneyCharacterIkhlasTakeaway1 =>
      'Aufrichtigkeit beginnt im Herzen, bevor sie in die Tat umgesetzt wird.';

  @override
  String get learningJourneyCharacterIkhlasTakeaway2 =>
      'Private Gottesdienste tragen dazu bei, die Aufrichtigkeit zu schützen.';

  @override
  String get learningJourneyCharacterIkhlasTakeaway3 =>
      'Ikhlas braucht eine regelmäßige Erneuerung, keine einmalige Entscheidung.';

  @override
  String get learningJourneyCharacterIkhlasReflection =>
      'Welcher Teil Ihres Gottesdienstes oder Gottesdienstes braucht eine ruhigere Absicht?';

  @override
  String get learningJourneyCharacterIkhlasActionStep =>
      'Wählen Sie heute eine kleine Tat, von der nur Allah weiß, dass Sie sie für Ihn beabsichtigt haben.';

  @override
  String get learningJourneyCharacterSabrTitle => 'Geduld (Sabr)';

  @override
  String get learningJourneyCharacterSabrIntro =>
      'Sabr ist keine passive Schwäche. Es ist beständiger Gehorsam, Selbstbeherrschung und Vertrauen auf Allah in der Schwierigkeit.';

  @override
  String get learningJourneyCharacterSabrSection1Title =>
      'Wo Geduld gefragt ist';

  @override
  String get learningJourneyCharacterSabrSection1Body =>
      'Geduld ist gefragt in Not, bei Verzögerungen, im Widerstand gegen die Sünde und im Beharren auf der Anbetung, wenn das Herz niedergeschlagen ist.';

  @override
  String get learningJourneyCharacterSabrSection2Title =>
      'Eine praktische Form des Säbels';

  @override
  String get learningJourneyCharacterSabrSection2Body =>
      'Sabr wirkt oft gewöhnlich: die eigene Reaktion zurücknehmen, eine Pflicht fortführen, ohne Klage warten und Allah um Hilfe bitten, bevor man spricht oder handelt.';

  @override
  String get learningJourneyCharacterSabrBullet1 =>
      'Halten Sie inne, bevor Sie reagieren, wenn Sie frustriert sind.';

  @override
  String get learningJourneyCharacterSabrBullet2 =>
      'Halten Sie auch an schwierigen Tagen eine Verpflichtung ein.';

  @override
  String get learningJourneyCharacterSabrBullet3 =>
      'Bitten Sie Allah um Hilfe, statt in Panik zu verfallen.';

  @override
  String get learningJourneyCharacterSabrTakeaway1 =>
      'Geduld ist aktive Stärke, keine Passivität.';

  @override
  String get learningJourneyCharacterSabrTakeaway2 =>
      'Sabr wird sowohl in Not als auch im Gehorsam benötigt.';

  @override
  String get learningJourneyCharacterSabrTakeaway3 =>
      'Kurze Pausen können Sie vor langem Bedauern bewahren.';

  @override
  String get learningJourneyCharacterSabrReflection =>
      'Wo müssen Sie am dringendsten langsamer werden und Allah mehr vertrauen?';

  @override
  String get learningJourneyCharacterSabrActionStep =>
      'Wenn Sie das nächste Mal Druck verspüren, halten Sie inne, atmen Sie und verzögern Sie Ihre Reaktion um einige Sekunden.';

  @override
  String get learningJourneyCharacterShukrTitle => 'Dankbarkeit (Shukr)';

  @override
  String get learningJourneyCharacterShukrIntro =>
      'Schukr bedeutet, Wohltaten von Allah zu erkennen und mit Lobpreis, Gehorsam und besserem Gebrauch des Gegebenen zu antworten.';

  @override
  String get learningJourneyCharacterShukrSection1Title =>
      'Dankbarkeit ist mehr als Worte';

  @override
  String get learningJourneyCharacterShukrSection1Body =>
      'Alhamdulillah zu sagen ist wichtig, doch Dankbarkeit umfasst auch, wie Sie Zeit, Gesundheit, Vermögen, Wissen und Beziehungen nutzen.';

  @override
  String get learningJourneyCharacterShukrSection2Title =>
      'Wie Dankbarkeit wächst';

  @override
  String get learningJourneyCharacterShukrSection2Body =>
      'Die Dankbarkeit wächst, wenn Sie bestimmte Segnungen wahrnehmen, sie benennen und sie in Anbetung und Dienst umwandeln, statt in einen Anspruch.';

  @override
  String get learningJourneyCharacterShukrBullet1 =>
      'Nennen Sie einen Segen klar und nicht vage.';

  @override
  String get learningJourneyCharacterShukrBullet2 =>
      'Nutzen Sie eine Wohltat auf eine Weise, die Allah liebt.';

  @override
  String get learningJourneyCharacterShukrBullet3 =>
      'Lassen Sie nicht zu, dass Trost Sie den Geber vergessen lässt.';

  @override
  String get learningJourneyCharacterShukrTakeaway1 =>
      'Dankbarkeit ist eine Reaktion von Herz, Zunge und Tat.';

  @override
  String get learningJourneyCharacterShukrTakeaway2 =>
      'Segnungen werden sicherer, wenn sie die Dankbarkeit steigern.';

  @override
  String get learningJourneyCharacterShukrTakeaway3 =>
      'Dankbarkeit schützt das Herz vor ständiger Unzufriedenheit.';

  @override
  String get learningJourneyCharacterShukrReflection =>
      'Welchen Segen haben Sie zu sehr daran gewöhnt, ihn mit Dankbarkeit wahrzunehmen?';

  @override
  String get learningJourneyCharacterShukrActionStep =>
      'Danken Sie Allah heute ausdrücklich für eine Wohltat und nutzen Sie sie dann auf eine gute Weise.';

  @override
  String get learningJourneyCharacterHumilityTitle => 'Demut';

  @override
  String get learningJourneyCharacterHumilityIntro =>
      'Demut bedeutet, das eigene Angewiesensein auf Allah klar zu sehen und Menschen ohne Überheblichkeit zu begegnen.';

  @override
  String get learningJourneyCharacterHumilitySection1Title =>
      'Demut und Wahrheit';

  @override
  String get learningJourneyCharacterHumilitySection1Body =>
      'Demut bedeutet nicht Schwäche oder Selbstauslöschung. Es bedeutet, die Wahrheit zu akzeptieren, den Stolz abzubauen und sich zu weigern, andere mit Überlegenheit zu behandeln.';

  @override
  String get learningJourneyCharacterHumilitySection2Title =>
      'Wie Arroganz Einzug hält';

  @override
  String get learningJourneyCharacterHumilitySection2Body =>
      'Arroganz kann sich hinter Wissen, Talent, Anbetung, Reichtum oder sozialer Stellung verbergen. Demut fragt: Höre ich immer noch zu, lerne ich und respektiere ich andere?';

  @override
  String get learningJourneyCharacterHumilityBullet1 =>
      'Akzeptieren Sie Korrekturen ohne Abwehrhaltung.';

  @override
  String get learningJourneyCharacterHumilityBullet2 =>
      'Messen Sie Menschen nicht nur nach ihrem Status oder ihrem äußeren Glanz.';

  @override
  String get learningJourneyCharacterHumilityBullet3 =>
      'Denken Sie daran, dass jede Gabe von Allah kommt.';

  @override
  String get learningJourneyCharacterHumilityTakeaway1 =>
      'Demut schützt Wissen davor, zu Stolz zu werden.';

  @override
  String get learningJourneyCharacterHumilityTakeaway2 =>
      'Ein bescheidener Mensch kann standhaft sein, ohne arrogant zu sein.';

  @override
  String get learningJourneyCharacterHumilityTakeaway3 =>
      'Das Gedenken Allahs verringert die Selbstwichtigkeit.';

  @override
  String get learningJourneyCharacterHumilityReflection =>
      'Inwiefern fällt es Ihnen durch Stolz schwerer, zuzuhören oder sich zu ändern?';

  @override
  String get learningJourneyCharacterHumilityActionStep =>
      'Hören Sie heute einer Person aufmerksam zu, ohne Ihre Antwort vorzubereiten, während sie spricht.';

  @override
  String get learningJourneyCharacterForgivenessTitle => 'Vergebung';

  @override
  String get learningJourneyCharacterForgivenessIntro =>
      'Vergebung macht das Herz weicher und befreit es davon, für immer jede Verletzung zu tragen.';

  @override
  String get learningJourneyCharacterForgivenessSection1Title =>
      'Was Vergebung ist und was nicht';

  @override
  String get learningJourneyCharacterForgivenessSection1Body =>
      'Vergebung bedeutet nicht, so zu tun, als wäre Schaden gut. Es bedeutet, den Wunsch loszulassen, den Groll weiter zu schüren, wenn Vergebung klug und sicher ist.';

  @override
  String get learningJourneyCharacterForgivenessSection2Title =>
      'Warum Vergebung wichtig ist';

  @override
  String get learningJourneyCharacterForgivenessSection2Body =>
      'Wenn ein Mensch um Allahs willen verzeiht, wird das Herz leichter. Vergebung kann Sie davor bewahren, von genau dem Schaden geprägt zu werden, den Sie erlitten haben.';

  @override
  String get learningJourneyCharacterForgivenessBullet1 =>
      'Bitten Sie Allah, Ihr Herz zu heilen, bevor Sie sich zu Worten zwingen.';

  @override
  String get learningJourneyCharacterForgivenessBullet2 =>
      'Behalten Sie Gerechtigkeit und Sicherheit im Blick, wo es nötig ist.';

  @override
  String get learningJourneyCharacterForgivenessBullet3 =>
      'Lassen Sie nicht zu, dass Groll zu Ihrer Identität wird.';

  @override
  String get learningJourneyCharacterForgivenessTakeaway1 =>
      'Vergebung ist am stärksten, wenn sie um Allahs willen geschieht.';

  @override
  String get learningJourneyCharacterForgivenessTakeaway2 =>
      'Ein weiches Herz kann immer noch kluge Grenzen wahren.';

  @override
  String get learningJourneyCharacterForgivenessTakeaway3 =>
      'Groll schadet dem, der ihn trägt.';

  @override
  String get learningJourneyCharacterForgivenessReflection =>
      'Gibt es eine Verletzung, die Sie vor Allah bringen müssen, damit sie Ihr Herz nicht länger beherrscht?';

  @override
  String get learningJourneyCharacterForgivenessActionStep =>
      'Machen Sie ein Dua zur Herzheilung, bevor Sie darüber nachdenken, wie Sie auf einen alten Schmerz reagieren sollen.';

  @override
  String get learningJourneyCharacterAngerTitle => 'Wut kontrollieren';

  @override
  String get learningJourneyCharacterAngerIntro =>
      'Wut selbst kann kommen, aber der islamische Charakter lehrt Zurückhaltung, bevor Wut zu Worten oder Schaden wird.';

  @override
  String get learningJourneyCharacterAngerSection1Title =>
      'Warum Wut Disziplin braucht';

  @override
  String get learningJourneyCharacterAngerSection1Body =>
      'Wut schränkt das Urteilsvermögen schnell ein. Ein einziger unkontrollierter Moment kann den Gottesdienst, die Beziehungen und das über Jahre aufgebaute Vertrauen schädigen.';

  @override
  String get learningJourneyCharacterAngerSection2Title =>
      'Wie man gut reagiert';

  @override
  String get learningJourneyCharacterAngerSection2Body =>
      'Treten Sie zurück, senken Sie Ihre Stimme, suchen Sie Zuflucht bei Allah, ändern Sie bei Bedarf Ihre Haltung und sprechen Sie nicht, solange das Herz noch entflammt ist.';

  @override
  String get learningJourneyCharacterAngerBullet1 =>
      'Beantworten Sie nicht jede Irritation sofort.';

  @override
  String get learningJourneyCharacterAngerBullet2 =>
      'Schweigen Sie vor bedauernden Worten.';

  @override
  String get learningJourneyCharacterAngerBullet3 =>
      'Kehren Sie zum Dhikr zurück, um das Herz abzukühlen.';

  @override
  String get learningJourneyCharacterAngerTakeaway1 =>
      'Zur Stärke gehört, dass man sich zurückhält, wenn man wütend ist.';

  @override
  String get learningJourneyCharacterAngerTakeaway2 =>
      'Die meisten Wutfehler passieren in den ersten Augenblicken.';

  @override
  String get learningJourneyCharacterAngerTakeaway3 =>
      'Eine ruhigere Reaktion schützt die Würde aller Beteiligten.';

  @override
  String get learningJourneyCharacterAngerReflection =>
      'Was passiert normalerweise, kurz bevor Ihre Wut zur Sprache wird?';

  @override
  String get learningJourneyCharacterAngerActionStep =>
      'Wählen Sie jetzt eine Gewohnheit zum Zurücksetzen: Schweigen, Haltungswechsel, Zurücktreten oder einen kurzen Dhikr sagen.';

  @override
  String get learningJourneyCharacterKindnessTitle => 'Freundlichkeit';

  @override
  String get learningJourneyCharacterKindnessIntro =>
      'Freundlichkeit ist eines der deutlichsten Zeichen dafür, dass Wissen das Herz erreicht hat.';

  @override
  String get learningJourneyCharacterKindnessSection1Title =>
      'Freundlichkeit im gewöhnlichen Leben';

  @override
  String get learningJourneyCharacterKindnessSection1Body =>
      'Freundlichkeit zeigt sich in kleinen Dingen: sanfte Sprache, geduldiges Zuhören, durchdachtes Timing, Service, Lächeln und Raum für andere schaffen.';

  @override
  String get learningJourneyCharacterKindnessSection2Title =>
      'Warum Gnade wichtig ist';

  @override
  String get learningJourneyCharacterKindnessSection2Body =>
      'Barmherzigkeit macht den Glauben sichtbar. Menschen spüren den Islam oft zuerst durch den Charakter eines Muslims, bevor sie seine tieferen Lehren verstehen.';

  @override
  String get learningJourneyCharacterKindnessBullet1 =>
      'Machen Sie Ihre Rede weicher, ohne unklar zu werden.';

  @override
  String get learningJourneyCharacterKindnessBullet2 =>
      'Suchen Sie nach einem verborgenen Bedürfnis, das Sie heute lindern können.';

  @override
  String get learningJourneyCharacterKindnessBullet3 =>
      'Behandeln Sie Ihre Familie und die Menschen, die Ihnen am nächsten stehen, mit besonderer Sorgfalt.';

  @override
  String get learningJourneyCharacterKindnessTakeaway1 =>
      'Freundlichkeit ist eine der stärksten Formen der Dawah im Alltag.';

  @override
  String get learningJourneyCharacterKindnessTakeaway2 =>
      'Barmherzigkeit gehört in Sprache, Dienst und Zurechtweisung.';

  @override
  String get learningJourneyCharacterKindnessTakeaway3 =>
      'Sanftmut öffnet oft Herzen, die mit Gewalt nicht erreicht werden können.';

  @override
  String get learningJourneyCharacterKindnessReflection =>
      'Wer in Ihrem täglichen Leben braucht gerade am meisten Sanftheit von Ihnen?';

  @override
  String get learningJourneyCharacterKindnessActionStep =>
      'Machen Sie heute eine kleine Geste der Sanftmut gegenüber jemandem, der Sie normalerweise in Eile sieht.';

  @override
  String get learningJourneyCharacterCompletionTitle => 'Abschlussreflexion';

  @override
  String get learningJourneyCharacterCompletionIntro =>
      'Sie haben das Ende dieser Reise erreicht. Jetzt besteht die Aufgabe nicht mehr aus Informationen. Es handelt sich um eine stetige Anwendung.';

  @override
  String get learningJourneyCharacterCompletionSection1Title =>
      'Schauen Sie ehrlich zurück';

  @override
  String get learningJourneyCharacterCompletionSection1Body =>
      'Welche Qualität war am einfachsten? Welche hat Ihre Schwäche offenbart? Ehrliche Reflexion macht zukünftiges Wachstum real.';

  @override
  String get learningJourneyCharacterCompletionSection2Title =>
      'Wählen Sie eine Eigenschaft aus, die Sie tragen möchten';

  @override
  String get learningJourneyCharacterCompletionSection2Body =>
      'Versuchen Sie nicht, alles auf einmal zu perfektionieren. Wählen Sie eine Eigenschaft, die in dieser Lebensphase am meisten Aufmerksamkeit erfordert, und kehren Sie immer wieder zu ihr zurück.';

  @override
  String get learningJourneyCharacterCompletionBullet1 =>
      'Wählen Sie eine Eigenschaft, nicht sieben.';

  @override
  String get learningJourneyCharacterCompletionBullet2 =>
      'Befestigen Sie es an einer täglichen Situation.';

  @override
  String get learningJourneyCharacterCompletionBullet3 =>
      'Besuchen Sie verwandte Reisen erneut, um sich zu stärken.';

  @override
  String get learningJourneyCharacterCompletionTakeaway1 =>
      'Der Charakter wächst durch Wiederholung, nicht durch Intensität allein.';

  @override
  String get learningJourneyCharacterCompletionTakeaway2 =>
      'Reflexion hilft Ihnen zu erkennen, wo Sie neu beginnen müssen.';

  @override
  String get learningJourneyCharacterCompletionTakeaway3 =>
      'Der beste Abschluss ist eine kleine laufende Veränderung.';

  @override
  String get learningJourneyCharacterCompletionReflection =>
      'An welcher einzelnen Charaktereigenschaft werden Sie in der nächsten Woche weiter arbeiten?';

  @override
  String get learningJourneyCharacterCompletionActionStep =>
      'Schreiben Sie eine Eigenschaft und eine Situation auf, in der Sie diese Woche bewusst üben werden.';

  @override
  String get learningJourneyDhikrRoutineActionStep =>
      'Wählen Sie einen Dhikr für den Morgen, einen für den Abend und einen nach der Salah, damit Ihre Routine klein und nachhaltig bleibt.';

  @override
  String get learningJourneyHadithEssentialsTitle => 'Hadith-Grundlagen';

  @override
  String get learningJourneyHadithEssentialsSubtitle =>
      'Beginnen Sie mit den grundlegendsten Hadith-Sammlungen und -Themen.';

  @override
  String get learningJourneyHadithEssentialsDescription =>
      'Verwenden Sie einen ruhigen Anfängerpfad, der erklärt, was ein Hadith ist, wie man beginnt und wie die Wiederholung das Verständnis stärkt.';

  @override
  String get learningJourneyHadithEssentialsOutcome1 =>
      'Verstehen Sie, warum Hadithe im täglichen muslimischen Leben wichtig sind';

  @override
  String get learningJourneyHadithEssentialsOutcome2 =>
      'Beginnen Sie mit grundlegenden Sammlungen und Themen';

  @override
  String get learningJourneyHadithEssentialsOutcome3 =>
      'Nutzen Sie Bewertungen als Verstärkung statt wahlloses Durchsuchen';

  @override
  String get learningJourneyHadithEssentialsWhyThisMatters =>
      'Hadithe begründen die alltägliche Praxis, den Charakter und das Verständnis prophetischer Führung.';

  @override
  String get learningJourneySalahFoundationsTitle => 'Gebet-Stiftungen';

  @override
  String get learningJourneySalahFoundationsSubtitle =>
      'Lernen, wie das Gebet verrichtet wird, Schritt für Schritt.';

  @override
  String get learningJourneySalahFoundationsDescription =>
      'Erfahren Sie, warum Salah wichtig ist, wie Sie sich darauf vorbereiten und wie seine Worte und Bewegungen zusammenwirken.';

  @override
  String get learningJourneySalahFoundationsOutcome1 =>
      'Verstehen Sie, warum Salah für einen muslimischen Tag von zentraler Bedeutung ist';

  @override
  String get learningJourneySalahFoundationsOutcome2 =>
      'Bereiten Sie sich mit Wudu, Absicht und Ruhe auf das Gebet vor';

  @override
  String get learningJourneySalahFoundationsOutcome3 =>
      'Verbinden Sie Bewegungen, Wörter, Bedeutung und Konsistenz';

  @override
  String get learningJourneySalahFoundationsWhyThisMatters =>
      'Das Gebet ist eine tägliche Säule, daher verändert selbst eine kleine Steigerung der Klarheit die gelebte Praxis schnell.';

  @override
  String get learningJourneyWuduJourneyTitle => 'Reise von Wudu';

  @override
  String get learningJourneyWuduJourneySubtitle =>
      'Lernen Sie die Reihenfolge des Wudu, seine Sunnah-Handlungen und wie man es übt.';

  @override
  String get learningJourneyWuduJourneyDescription =>
      'Gehen Sie vom Verstehen des Wudu zum Üben über, prüfen Sie, woran es scheitert, und vermeiden Sie häufige Fehler.';

  @override
  String get learningJourneyWuduJourneyOutcome1 =>
      'Verstehen Sie, warum Wudu vor dem Gebet wichtig ist';

  @override
  String get learningJourneyWuduJourneyOutcome2 =>
      'Üben Sie die Sequenz mit Zuversicht';

  @override
  String get learningJourneyWuduJourneyOutcome3 =>
      'Erkennen Sie, was Wudu bricht, und wie Sie sich ruhig selbst überprüfen können';

  @override
  String get learningJourneyWuduJourneyWhyThisMatters =>
      'Wudu ist das tägliche Tor zur Salah, daher beseitigt die Klarheit hier Reibungen bei der Anbetung.';

  @override
  String get learningJourneyRamadanFoundationsTitle => 'Ramadan-Stiftungen';

  @override
  String get learningJourneyRamadanFoundationsSubtitle =>
      'Ein stufenweiser Vorbereitungspfad für das Fasten und den Ramadan-Gottesdienst.';

  @override
  String get learningJourneyRamadanFoundationsDescription =>
      'Gehen Sie einen einfachen Anfängerpfad entlang, der Fasten, Tagesrhythmus, spirituelle Ziele und häufige Fehler im Ramadan erklärt.';

  @override
  String get learningJourneyRamadanFoundationsOutcome1 =>
      'Verstehen Sie, was Ramadan ist und warum Muslime fasten';

  @override
  String get learningJourneyRamadanFoundationsOutcome2 =>
      'Bauen Sie einen praktischen Rhythmus von Suhoor bis Iftar auf';

  @override
  String get learningJourneyRamadanFoundationsOutcome3 =>
      'Tragen Sie den Ramadan mit Bedacht, Sorgfalt und spirituellen Zielen';

  @override
  String get learningJourneyRamadanFoundationsWhyThisMatters =>
      'Der Ramadan hat eine große Wirkung und ist zeitgebunden, sodass er von einem speziellen, geführten Vorbereitungspfad profitiert.';

  @override
  String get learningJourneyArabicAlphabetTitle => 'Arabische Alphabet-Reise';

  @override
  String get learningJourneyArabicAlphabetSubtitle =>
      'Mit den Buchstaben und ihren Lauten beginnen.';

  @override
  String get learningJourneyArabicAlphabetDescription =>
      'Lernen Sie die arabischen Buchstaben in ruhigen Gruppen, verstärken Sie ihren Klang und entwickeln Sie eine nützliche Wiederholungsgewohnheit, bevor Sie mit dem Lesen beginnen.';

  @override
  String get learningJourneyArabicAlphabetOutcome1 =>
      'Erkennen Sie die arabischen Buchstaben in überschaubaren Gruppen';

  @override
  String get learningJourneyArabicAlphabetOutcome2 =>
      'Verbessern Sie die Aussprache durch Wiederholung';

  @override
  String get learningJourneyArabicAlphabetOutcome3 =>
      'Entwickeln Sie eine Wiederholungsgewohnheit, die Sie auf die Grundlagen des Lesens vorbereitet';

  @override
  String get learningJourneyArabicAlphabetWhyThisMatters =>
      'Buchstabensicherheit ist die erste wirkliche Schwelle zum Koran-Arabisch und zum Lesen.';

  @override
  String get learningJourneyReadingBasicsTitle => 'Lesegrundlagen';

  @override
  String get learningJourneyReadingBasicsSubtitle =>
      'Von den Buchstaben zum Lesen.';

  @override
  String get learningJourneyReadingBasicsDescription =>
      'Überbrücken Sie das Alphabet in Harakat, verbundene Buchstaben und ruhige Lesekontrollpunkte, bevor Sie es weiter rezitieren.';

  @override
  String get learningJourneyReadingBasicsOutcome1 =>
      'Erkennen Sie die Kernlesezeichen und wie sie den Klang verändern';

  @override
  String get learningJourneyReadingBasicsOutcome2 =>
      'Gehen Sie von einzelnen Buchstaben zum gemeinsamen Lesen über';

  @override
  String get learningJourneyReadingBasicsOutcome3 =>
      'Nutzen Sie Wiederholungsschleifen, bevor Sie mit der umfassenderen Rezitation fortfahren';

  @override
  String get learningJourneyReadingBasicsWhyThisMatters =>
      'Zwischen dem Erlernen der Buchstaben und dem Rezitieren ganzer Verse brauchen die meisten einen Zwischenschritt.';

  @override
  String get learningJourneyTriviaPathsTitle => 'Trivia-Wissenspfade';

  @override
  String get learningJourneyTriviaPathsSubtitle =>
      'Geführte Trivia-Pfade, die immer noch der Reihe nach unterrichten.';

  @override
  String get learningJourneyTriviaPathsDescription =>
      'Nutzen Sie Wissenswertes als Verstärkung mit einer klaren Pfadauswahl, fokussierten Sitzungen und geführten Nachbereitungen zu tieferen Reisen.';

  @override
  String get learningJourneyTriviaPathsOutcome1 =>
      'Wählen Sie einen Trivia-Pfad mit einem Lernzweck';

  @override
  String get learningJourneyTriviaPathsOutcome2 =>
      'Nutzen Sie kurze Sitzungen als Verstärkung und nicht als isoliertes Spiel';

  @override
  String get learningJourneyTriviaPathsOutcome3 =>
      'Kehren Sie von der Rezension zu verwandten Reisen zurück, um mehr Tiefe zu erlangen';

  @override
  String get learningJourneyTriviaPathsWhyThisMatters =>
      'Gut aufgebautes Trivia ist ein leichter Weg zu strukturiertem Wissen.';

  @override
  String get learningJourneyStageHadithEssentialCollectionTitle =>
      'Warum Hadithe wichtig sind';

  @override
  String get learningJourneyStageHadithEssentialCollectionSummary =>
      'Beginnen Sie mit einem einfachen Rahmen dafür, wie Hadithe Anbetung, Charakter und tägliches Leben leiten.';

  @override
  String get learningJourneyStageHadithThemesTitle => 'Sammlungen und Themen';

  @override
  String get learningJourneyStageHadithThemesSummary =>
      'Erfahren Sie, wie Sie mit wichtigen Sammlungen beginnen und dann ohne Überlastung nach Themen suchen.';

  @override
  String get learningJourneyStageHadithReviewTitle =>
      'Wiederholen Sie die Lektion und leben Sie sie';

  @override
  String get learningJourneyStageHadithReviewSummary =>
      'Nutzen Sie die Rezension als Verstärkung und verknüpfen Sie das Gelesene mit dem Charakter und der täglichen Weisheit.';

  @override
  String get learningJourneyStageSalahWhyTitle => 'Warum wir beten';

  @override
  String get learningJourneyStageSalahWhySummary =>
      'Beginnen Sie mit der Bedeutung des Salah als täglicher Begegnung mit Allah und als Anker des Gottesdienstes.';

  @override
  String get learningJourneyStageSalahPrepareTitle =>
      'Bereiten Sie sich auf das Gebet vor';

  @override
  String get learningJourneyStageSalahPrepareSummary =>
      'Erfahren Sie, wie Wudu, Absicht, Timing und Ruhe Herz und Körper auf Salah vorbereiten.';

  @override
  String get learningJourneyStageSalahMovementsTitle => 'Bewegungen der Salah';

  @override
  String get learningJourneyStageSalahMovementsSummary =>
      'Gehen Sie die Gebetshaltung Haltung für Haltung durch, sodass sich die Abfolge ruhig und verständlich anfühlt.';

  @override
  String get learningJourneyStageSalahWordsMeaningTitle =>
      'Was die Worte bedeuten';

  @override
  String get learningJourneyStageSalahWordsMeaningSummary =>
      'Verbinden Sie die Worte des Salah mit der Bedeutung, damit Aufmerksamkeit und Khushu beginnen, zusammenzuwachsen.';

  @override
  String get learningJourneyStageSalahConsistencyTitle =>
      'Konsistenz und Khushu';

  @override
  String get learningJourneyStageSalahConsistencySummary =>
      'Erstellen Sie abschließend einen realistischen Rhythmus für das Schutzgebet und die Wiederkehr nach schwachen Tagen.';

  @override
  String get learningJourneyStageSalahCompletionTitle =>
      'Tragen Sie Salah vorwärts';

  @override
  String get learningJourneyStageSalahCompletionSummary =>
